mapper.select:
SELECT qtr.id AS qcTreatmentId, qtr.adm_no AS admNo, qci.customer_name AS customerName, qci.mobile AS customerMobile, qtr.patient_id AS patientId, qtr.type, qtr.status, qtr.order_record_id AS billId, qtr.bill_pay_id AS billPayId, qtr.upd_id AS updId, qtr.upd_time AS updTime, IFNULL(qti.executeAmount, 0) AS executeAmount, IFNULL(qti.unExecuteAmount, 0) AS unExecuteAmount FROM qc_treatment_record qtr LEFT JOIN qc_customer_info qci ON qtr.id = qci.qc_treatment_id LEFT JOIN ( SELECT qc_treatment_id, received_amount AS executeAmount, price * quantity - received_amount AS unExecuteAmount FROM qc_treatment_item WHERE qc_collected = 1 AND inservice = 1 GROUP BY qc_treatment_id ) qti ON qti.qc_treatment_id = qtr.id
AND qtr.status in(3, 4) AND qtr.inservice = 1
AND qtr.id = #{id}
AND DATE_FORMAT(qtr.upd_time, '%Y-%m-%d') BETWEEN #{startDate} AND #{endDate}
